# Extract blocks
def extract_blocks(grid):
    rows_sep = [i for i, row in enumerate(grid) if all(c == 2 for c in row)]
    cols_sep = [j for j in range(len(grid[0])) if all(cell[j] == 2 for cell in grid)]

    # Block row indices ranges
    row_ranges = []
    prev = 0
    for r in rows_sep:
        if r > prev:
            row_ranges.append((prev, r - 1))
        prev = r + 1
    if prev < len(grid):
        row_ranges.append((prev, prev))

    col_ranges = []
    prev = 0
    for c in cols_sep:
        if c > prev:
            col_ranges.append((prev, c - 1))
        prev = c + 1
    if prev < len(grid[0]):
        col_ranges.append((prev, prev))

    blocks = []
    for ri, (r_start, r_end) in enumerate(row_ranges):
        for ci, (c_start, c_end) in enumerate(col_ranges):
            block = grid[r_start:r_end+1][c_start:c_end+1]
            blocks.append((ri, ci, block))
    return blocks

